package android.media;import android.os.Handler;public final class ImageReader {public Handler handler;public boolean working;public int closes;public interface OnImageAvailableListener{void onImageAvailable(ImageReader r);}public void setOnImageAvailableListener(OnImageAvailableListener l,Handler h){if(l!=null)handler=h;}public void close(){if(working)throw new AssertionError("concurrent reader close");closes++;}}
